from pathlib import Path
import json,hashlib,subprocess,importlib.metadata,warnings
from jsonschema import Draft202012Validator,Draft7Validator,RefResolver
r=Path.cwd();f=r/'tests/fixtures/attestara/C04'
schemas={n:json.loads((r/'contracts'/f'{n}.schema.json').read_text()) for n in ['input','result']}
for s in schemas.values():Draft202012Validator.check_schema(s)
for name,target in [('input.valid.json','input'),('result.valid.json','result'),('result.failed.json','result')]:Draft202012Validator(schemas[target]).validate(json.loads((f/name).read_text()))
extra={'missing-policy-file','duplicate-path'}
for case in json.loads((f/'negative.json').read_text())['cases']:
 errors=list(Draft202012Validator(schemas[case['target']]).iter_errors(case['value']))
 assert bool(errors)==(case['id'] not in extra),case['id']
source=Path('/tmp/attestara-c02/cyclonedx-proof/specification-349314a9d7671d7d2ca5b711a725f49a73979da6/schema/bom-1.7.schema.json')
schema=json.loads(source.read_text());Draft7Validator(schema,resolver=RefResolver(source.as_uri(),schema)).validate(json.loads((f/'sbom.cdx.json').read_text()))
print('Draft202012 schemas valid; 3 positive fixtures and '+str(len(json.loads((f/'negative.json').read_text())['cases']))+' negative fixtures checked (2 require Go cross-field invariants).')
print('Synthetic SBOM validates against C02-pinned CycloneDX 1.7 source; bom schema sha256:'+hashlib.sha256(source.read_bytes()).hexdigest())
print('Validation tool: jsonschema '+importlib.metadata.version('jsonschema')+'; test-only preinstalled Python library, no runtime dependency added.')
proof=json.loads((r/'docs/evidence/C03.json').read_text()); mismatches=[]
for path,want in proof['source_files'].items():
 b=subprocess.check_output(['git','show','HEAD:'+path]);
 if hashlib.sha256(b).hexdigest()!=want:mismatches.append(path)
assert not mismatches,mismatches
print('All '+str(len(proof['source_files']))+' recorded C03 source hashes match HEAD before C04 changes.')
for n in ['input','result']:
 old=subprocess.check_output(['git','show','HEAD:contracts/'+n+'.schema.json']);assert old==(r/'contracts/drafts'/f'{n}.v0.schema.json').read_bytes()
print('Both archived draft schemas exactly match pre-C04 bytes.')
